// Normalise la réponse REST et s'arrête si aucun sujet en attente.
const body = $input.first().json;
const rows = Array.isArray(body) ? body : (body.data ?? (body && body.id ? [body] : []));
if (!rows.length) return [];           // file vide => le workflow s'arrête proprement
return [{ json: rows[0] }];

// Récupère l'UUID du cluster à partir de son slug, et le rattache au sujet.
const cat = $input.first().json;
const rows = Array.isArray(cat) ? cat : (cat.data ?? (cat && cat.id ? [cat] : []));
const topic = $('Pick topic').item.json;
if (!rows.length) throw new Error('Cluster introuvable pour slug: ' + topic.cluster_slug);
return [{ json: { ...topic, category_id: rows[0].id } }];

// Construit le corps de la requête Claude (Messages API + tool_use forcé).
const t = $input.first().json;
const SYSTEM = "Tu es un rédacteur SEO expert pour ClubsVoile.fr, l'annuaire national des clubs de voile en France. Tu écris en français des articles de blog clairs, fiables et optimisés pour le référencement naturel.\n\nRÈGLES IMPÉRATIVES\n- Public : grand public francophone qui veut apprendre la voile, choisir un support ou un club.\n- Ton : accessible, concret, honnête (E-E-A-T). N'invente JAMAIS de prix précis, d'avis, de statistiques ou de faits invérifiables. Reste sur des fourchettes prudentes et des principes généraux.\n- Contenu en HTML sémantique : <h2>, <h3>, <p>, <ul>/<li>, <strong>. JAMAIS de <h1> (le titre est séparé). Aucun style inline, aucune classe.\n- Longueur : 650 à 1100 mots, utile, sans remplissage.\n- Structure : commence par 1-2 paragraphes d'introduction (pas de <h2> en tout premier), puis 3 à 5 sections <h2>.\n- MAILLAGE INTERNE OBLIGATOIRE : insère 2 à 4 liens <a href=\"...\"> vers l'annuaire, là où c'est pertinent. Cibles autorisées : /stage-de-voile, /ecole-de-voile, /club-de-voile, /activites, et les activités /optimist /catamaran /deriveur /wingfoil /windfoil /planche-a-voile-windsurf /kitesurf /kayak /paddle /surf /e-foil. N'invente pas d'autres URLs.\n- slug : court, en kebab-case, reflète le mot-clé cible (sans accents).\n- meta_title : <= 60 caractères. meta_description : <= 155 caractères, incitative.\n- excerpt : 1 à 2 phrases qui résument l'article (sert de chapô et de fallback meta).\n- faq : 2 à 4 questions/réponses réellement utiles. Les réponses peuvent contenir du HTML léger.\n- cover_alt : description courte et descriptive de l'image de couverture.\n- reading_minutes : estimation honnête (~200 mots/min).\n\nTu réponds UNIQUEMENT en appelant l'outil save_article. Aucun texte hors de l'outil.";
const SCHEMA = {"type":"object","properties":{"title":{"type":"string","description":"Titre H1 de l’article"},"slug":{"type":"string","description":"kebab-case, sans accents, dérivé du mot-clé"},"excerpt":{"type":"string","description":"Résumé 1-2 phrases"},"content_html":{"type":"string","description":"Corps en HTML sémantique (h2/h3/p/ul/strong/a), sans h1"},"meta_title":{"type":"string","description":"<= 60 caractères"},"meta_description":{"type":"string","description":"<= 155 caractères"},"cover_alt":{"type":"string","description":"Texte alternatif de l’image de couverture"},"tags":{"type":"array","items":{"type":"string"},"description":"3 à 6 tags"},"faq":{"type":"array","description":"2 à 4 questions/réponses","items":{"type":"object","properties":{"q":{"type":"string"},"a":{"type":"string"}},"required":["q","a"],"additionalProperties":false}},"reading_minutes":{"type":"integer","description":"Temps de lecture estimé en minutes"}},"required":["title","slug","excerpt","content_html","meta_title","meta_description","cover_alt","tags","faq","reading_minutes"],"additionalProperties":false};
const user = [
  'Rédige un article de blog optimisé SEO pour ClubsVoile.fr.',
  '',
  'Mot-clé cible : ' + t.keyword,
  'Cluster (thématique) : ' + t.cluster_slug,
  'Intention de recherche : ' + (t.search_intent || 'informationnelle'),
  'Angle / titre suggéré : ' + (t.title_hint || '(libre, choisis le meilleur)'),
  'Consignes : ' + (t.notes || '(aucune)'),
  '',
  'Respecte toutes les règles du system prompt (HTML sémantique, maillage interne, méta, FAQ).'
].join('\n');

const claudeBody = {
  model: 'claude-opus-4-8',
  max_tokens: 8000,
  system: SYSTEM,
  tools: [{
    name: 'save_article',
    description: 'Enregistre l\'article de blog optimisé SEO, prêt à publier.',
    input_schema: SCHEMA,
    strict: true
  }],
  tool_choice: { type: 'tool', name: 'save_article' },
  messages: [{ role: 'user', content: user }]
};
return [{ json: { ...t, claudeBody } }];

// Extrait le tool_use de la réponse Claude et construit la ligne blog_posts.
const resp = $input.first().json;
const blocks = resp.content || [];
const tool = blocks.find(b => b.type === 'tool_use');
if (!tool) throw new Error('Réponse Claude sans tool_use: ' + JSON.stringify(resp).slice(0, 400));
const a = tool.input;
const t = $('Resolve category').item.json;

const slug = String(a.slug || a.title)
  .toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const row = {
  slug,
  category_id: t.category_id,
  title: a.title,
  excerpt: a.excerpt,
  content_html: a.content_html,
  cover_image: t.cover_image || null,
  cover_alt: a.cover_alt || null,
  meta_title: a.meta_title,
  meta_description: a.meta_description,
  tags: a.tags || [],
  faq: a.faq || [],
  reading_minutes: a.reading_minutes || null,
  author: 'L\'équipe ClubsVoile.fr',
  status: 'published',          // mets 'draft' si tu veux relire avant publication
  published_at: new Date().toISOString()
};
return [{ json: row }];
